contract InvMutTest {
    C c;
    uint256 public initialOwnerBalanceSnapshot; // not used in assertion, just to allow storage
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to forward to c.go; the test contract must hold at least that amount
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record balances before the call
        uint256 beforeTestBal = address(this).balance;
        uint256 beforeCbal = address(c).balance;
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // call c.go forwarding `amount` wei
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-state
        uint256 afterTestBal = address(this).balance;
        uint256 afterCbal = address(c).balance;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: calling c.go cannot increase this contract's balance beyond losing at most `amount`.
        // That is: afterTestBal >= beforeTestBal - amount
        // Also owner of c must remain equal to pre-call owner (observable invariant)
        assert(afterTestBal >= beforeTestBal - amount && ownerAfter == ownerBefore);
    }

    // fallback to accept refunds if any
    receive() external payable {}
}

